// Keep future deployments from mixing cached files. Reload remains a teacher decision.
const OXFORD_RELEASE='geography-adventures-2026-09-13';
document.addEventListener('DOMContentLoaded',()=>{let checking=false,shown=false;async function check(){if(checking||shown||document.hidden)return;checking=true;try{const r=await fetch('./release.json',{cache:'no-store'});if(!r.ok)return;const latest=await r.json();if(latest.version!==OXFORD_RELEASE){shown=true;const box=document.createElement('aside');box.className='gx-update';box.setAttribute('role','status');box.innerHTML='<strong>An Oxford update is ready</strong><p>Finish or save your lesson, then reload to get the newest games.</p><button>Reload Oxford</button><button>Later</button>';const buttons=box.querySelectorAll('button');buttons[0].onclick=()=>{if(typeof dirty!=='undefined'&&dirty&&!confirm('Save or download your lesson before reloading. Reload and discard unsaved edits?'))return;const url=new URL(location.href);url.searchParams.set('release',latest.version);location.href=url.href;};buttons[1].onclick=()=>box.remove();document.body.append(box);}}catch{}finally{checking=false;}}window.addEventListener('focus',check);setInterval(check,300000);check();});
